def translate(key: str, language: str = "en-US") -> str:
    """Translate a string key to the specified language.

    Args:
        key: Translation key (e.g., "header.logo")
        language: Language code (e.g., "en-US", "es-ES", "fr-FR")

    Returns:
        Translated string, or the key itself if not found.
        Falls back to English if language not available.
    """
    if key in TRANSLATIONS:
        return TRANSLATIONS[key].get(language, TRANSLATIONS[key].get("en-US", key))
    return key


def get_supported_languages() -> dict:
    """Get list of all supported languages with native names."""
    from src.language_registry import LanguageRegistry
    return {code: LanguageRegistry.get_native_name(code) for code in TRANSLATIONS.get("header.logo", {}).keys() if code != "en-US"}
